import express from 'express';
import { supabaseAdmin, supabaseAdminConfigured } from '../lib/supabaseServer.js';
import { validateRequest, schemas } from '../lib/validation.js';
import { successResponse, errorResponse, asyncHandler } from '../lib/apiResponse.js';
import { requireActiveAccount } from '../lib/authz.js';
import { readPaymentMethodSettings } from '../lib/paymentMethods.js';

const router = express.Router();

// All payment fields that affect money are generated by the server. Clients
// cannot write payment rows or choose a credited amount through PostgREST.
router.post(
  '/create',
  requireActiveAccount,
  validateRequest(schemas.createPaymentSchema),
  asyncHandler(async (req, res) => {
    if (!supabaseAdminConfigured || !supabaseAdmin) {
      return res.status(503).json(errorResponse('PAYMENTS_UNAVAILABLE', 'Payment service is not configured.'));
    }
    const amount = Math.round(Number(req.validatedBody.amount) * 100) / 100;
    const fee = Math.round(amount * 2) / 100;
    const total = Math.round((amount + fee) * 100) / 100;
    const { data: payment, error } = await supabaseAdmin
      .from('payments')
      .insert({
        user_id: req.user.id,
        amount,
        fee,
        total,
        payment_method: 'fastpay',
        payment_provider: 'fastpay',
        status: 'pending',
      })
      .select('id, user_id, amount, fee, total, payment_method, payment_provider, status, created_at')
      .single();
    if (error) throw error;
    return res.status(201).json(successResponse({ payment }));
  })
);

// Manual transfers are always created as pending deposits. Wallet balance is
// credited only after an administrator verifies the transfer through the review RPC.
router.post('/manual-deposit', requireActiveAccount, asyncHandler(async (req, res) => {
  if (!supabaseAdminConfigured || !supabaseAdmin) {
    return res.status(503).json(errorResponse('PAYMENTS_UNAVAILABLE', 'Payment service is not configured.'));
  }
  const amountInput = Number(req.body?.amount);
  const methodId = String(req.body?.methodId || '').trim().toLowerCase();
  const transactionReference = String(req.body?.transactionReference || '').trim();
  if (!Number.isFinite(amountInput) || amountInput < 5 || amountInput > 10000 ||
      !/^[a-z0-9][a-z0-9_-]{1,39}$/.test(methodId) ||
      transactionReference.length < 3 || transactionReference.length > 100) {
    return res.status(400).json(errorResponse('INVALID_MANUAL_DEPOSIT', 'Enter a valid amount, payment method, and transaction reference.'));
  }

  const { methods } = await readPaymentMethodSettings(supabaseAdmin);
  const method = methods.find((item) => item.id === methodId && item.active);
  if (!method) {
    return res.status(400).json(errorResponse('PAYMENT_METHOD_UNAVAILABLE', 'This payment method is not currently available.'));
  }
  const amount = Math.round(amountInput * 100) / 100;
  if (amount < method.minimumAmount) {
    return res.status(400).json(errorResponse('BELOW_MINIMUM', `Minimum deposit for ${method.name} is ${method.minimumAmount}.`));
  }

  const { data: payment, error } = await supabaseAdmin
    .from('payments')
    .insert({
      user_id: req.user.id,
      amount,
      fee: 0,
      total: amount,
      payment_method: method.id,
      payment_provider: 'manual',
      transaction_id: transactionReference,
      status: 'pending',
      metadata: {
        manual_method: { id: method.id, name: method.name },
        customer_reference: transactionReference,
      },
    })
    .select('id, user_id, amount, fee, total, payment_method, payment_provider, transaction_id, status, created_at')
    .single();
  if (error) {
    if (String(error.code || '') === '23505') {
      return res.status(409).json(errorResponse('DUPLICATE_TRANSACTION_REFERENCE', 'This transaction reference has already been submitted.'));
    }
    throw error;
  }
  return res.status(201).json(successResponse({ payment }));
}));

// PayFast's completion/webhook path is not implemented as an atomic,
// amount-verified credit. Keep it deliberately disabled rather than imply
// success or accept client-supplied redirect/payment details.
router.post('/payfast', requireActiveAccount, (_req, res) =>
  res.status(503).json(errorResponse('PAYFAST_UNAVAILABLE', 'PayFast deposits are temporarily unavailable.'))
);
router.post('/payfast-webhook', (_req, res) =>
  res.status(503).json(errorResponse('PAYFAST_UNAVAILABLE', 'PayFast notifications are disabled.'))
);

router.get('/methods', asyncHandler(async (_req, res) => {
  const fastpayAvailable = Boolean(
    process.env.FASTPAY_API_KEY &&
    process.env.FASTPAY_MERCHANT_ID &&
    process.env.FASTPAY_WEBHOOK_SECRET &&
    process.env.FASTPAY_WEBHOOK_URL
  );
  const { methods: manualMethods, settings } = await readPaymentMethodSettings(supabaseAdmin);
  const fastpayEnabled = fastpayAvailable && settings.fastpayEnabled !== false;
  const methods = [
    {
      id: 'fastpay', name: 'FastPay', region: 'MENA / Global', type: 'gateway',
      available: fastpayEnabled, endpoint: '/api/fastpay/create-order',
    },
    {
      id: 'payfast', name: 'PayFast', region: 'ZA / Global', type: 'gateway',
      available: false, comingSoon: true, endpoint: '/api/payments/payfast',
    },
    { id: 'credit_card', name: 'Credit / Debit Card', region: 'Global', type: 'gateway', available: false, comingSoon: true },
    { id: 'easypaisa', name: 'EasyPaisa', region: 'Pakistan', type: 'gateway', available: false, comingSoon: true },
    { id: 'paypal', name: 'PayPal', region: 'Global', type: 'gateway', available: false, comingSoon: true },
    { id: 'crypto', name: 'Crypto (USDT / BTC)', region: 'Global', type: 'gateway', available: false, comingSoon: true },
    ...manualMethods.filter((method) => method.active).map((method) => ({
      id: method.id,
      name: method.name,
      region: method.region || 'Manual transfer',
      type: 'manual',
      available: true,
      minimumAmount: method.minimumAmount,
      accountName: method.accountName,
      accountDetails: method.accountDetails,
      instructions: method.instructions,
    })),
  ];
  return res.status(200).json(successResponse({ methods }));
}));

export default router;
